                   ("أربعة", "٤", "#6CC27A"), ("خمسة", "٥", "#6CB8FF"), ("ستة", "٦", "#B9A2F0"), ("سبعة", "٧", "#F59BB8"), ("ثمانية", "٨", "#E8574A"), ("تسعة", "٩", "#F6A04D"),
